'use strict';
const learningFilters={query:'',kind:'All',placement:'All',week:'All',status:'All'};
let learningSaving=false;
let learningPage=0;
const updateFilters={source:'All',date:''};
let attemptNonce=null;
function learningValue(value){if(Array.isArray(value))return `<ul>${value.map(v=>`<li>${learningValue(v)}</li>`).join('')}</ul>`;if(value&&typeof value==='object')return Object.entries(value).map(([key,v])=>`<div class="section"><strong>${esc(key.replaceAll('_',' '))}</strong>${learningValue(v)}</div>`).join('');return `<p>${esc(value)}</p>`}
function learningDetailExtras(id){const item=arr(curriculum().items).find(i=>i.id===id);if(!item)return;const fields=['source_outline','task','done_when','acceptance','stop','criteria'].filter(k=>item[k]);const related=arr(item.related_ids).filter(pid=>!arr(item.prerequisite_ids).includes(pid)&&pid!==id);if(!fields.length&&!related.length)return;$('#detail-body').insertAdjacentHTML('beforeend',`<section class="section"><h3>Study outline & acceptance evidence</h3>${fields.map(key=>`<details class="section" open><summary>${esc(key.replaceAll('_',' '))}</summary>${learningValue(item[key])}</details>`).join('')}${related.length?`<h3>Related learning</h3><div class="resource-list">${related.map(pid=>itemButton(pid,curriculum().items.find(i=>i.id===pid)?.title||pid)).join('')}</div>`:''}</section>`);bindLearningItems()}
function openLearningItem(id){openLearningDetails(id);learningDetailExtras(id);attemptNonce=id+':'+Date.now()+':'+Math.random().toString(36).slice(2);const item=arr(curriculum().items).find(i=>i.id===id);if(item?.kind!=='checkpoint')return;const ids=[...new Set([...arr(item.evidence_ids),...arr(item.prerequisite_ids)])];$('#detail-body').insertAdjacentHTML('beforeend',`<section class="section"><h3>Checkpoint evidence review</h3><p class="small muted">Review the linked proof and attempts; completion alone is not readiness.</p>${ids.map(pid=>{const entry=arr(curriculum().items).find(i=>i.id===pid),progress=learning().states?.[pid]||{},attempts=arr(learning().attempts).filter(a=>a.item_id===pid||a.id===pid);return `<details class="card section"><summary>${esc(entry?.title||pid)} · ${esc(learningStatus(pid))} · ${attempts.length} attempts</summary>${itemButton(pid)}<p>${esc(progress.notes||'No notes recorded.')}</p><p><strong>Evidence:</strong> ${esc(progress.evidence||'No evidence recorded.')}</p>${attempts.map(a=>`<p>Day ${esc(a.day)} · ${esc(a.outcome)} · score ${esc(a.score??'not scored')}<br>${esc(a.evidence||a.notes)}</p>`).join('')}</details>`}).join('')||'<p>No linked evidence items specified.</p>'}</section>`);bindLearningItems()}
function renderCurriculumReview(){const urls=[...new Set(arr(curriculum().source_inventory).map(s=>s.source_url||s.url).filter(Boolean))],all=arr(learning().snapshots),snapshots=all.filter(s=>(updateFilters.source==='All'||s.source_url===updateFilters.source)&&(!updateFilters.date||String(s.observed_at).startsWith(updateFilters.date)));$('#app').innerHTML=`<section class="narrow section"><h2>Curriculum updates</h2><p>Stage source changes, review the diff, then adopt individual references. Daily assignments stay fixed.</p></section><div class="toolbar"><label class="grow">Configured source<select id="curriculum-source">${urls.map(u=>`<option value="${esc(u)}">${esc(u)}</option>`).join('')}</select></label><button id="curriculum-refresh" ${urls.length?'':'disabled'}>Refresh source</button><label>Snapshot source<select id="snapshot-source">${options(['All',...urls],updateFilters.source)}</select></label><label>Observed date<input id="snapshot-date" type="date" value="${esc(updateFilters.date)}"></label></div><details class="section"><summary>Import a source snapshot manually</summary><p>Paste JSON: {source_url, observed_at, complete, items:[{url,title,access,summary,kind}]}. The source must be configured. observed_at is an ISO date; access describes availability. Use complete:false for partial inventories so missing entries are not removals.</p><textarea id="curriculum-import"></textarea><button id="curriculum-import-save">Stage import</button></details><p id="curriculum-error" class="danger" role="alert"></p><section class="section"><h2>Staged snapshots (${snapshots.length})</h2>${snapshots.map(s=>{const diff=s.diff||{},changed=[...arr(diff.additions),...arr(diff.changes)].map(x=>typeof x==='string'?x:x.id||x.item_id||x.url),review=arr(s.items).filter(i=>changed.includes(i.id)||changed.includes(i.url));return `<details class="card section"><summary>${esc(s.source_url)} · ${s.baseline?'Baseline inventory · ':''}${esc(s.observed_at)} · ${arr(diff.additions).length} additions, ${arr(diff.changes).length} changes, ${arr(diff.removals).length} removals</summary>${['additions','changes','removals'].map(k=>`<details class="section"><summary>${esc(k)} (${arr(diff[k]).length})</summary><ul>${arr(diff[k]).map(v=>`<li>${esc(typeof v==='string'?v:v.title||v.url||v.id||JSON.stringify(v))}</li>`).join('')||'<li>None</li>'}</ul></details>`).join('')}<h3>Added or changed references</h3>${review.map(i=>{const baseline=arr(curriculum().items).find(c=>c.id===i.id)||arr(curriculum().items).find(c=>c.url===i.url);return `<div class="section">${link(i.url,i.title)} <span class="chip">${esc(i.access)}</span><p>${esc(i.summary)}</p>${baseline?`<p class="small muted">Existing catalog: ${esc(baseline.title)} · ${esc(baseline.placement)}</p>${itemButton(baseline.id)}`:''}<button data-adopt-snapshot="${esc(s.id)}" data-adopt-item="${esc(i.id)}">Adopt as reference</button></div>`}).join('')||'<p class="muted">No additions or changed references to adopt.</p>'}</details>`}).join('')||'<p class="muted">No staged snapshots match these filters.</p>'}</section><details class="section"><summary>Adopted references (${arr(learning().adoptions).length})</summary>${arr(learning().adoptions).map(i=>`<p>${link(i.url,i.title)} ${itemButton(i.id)}</p>`).join('')||'<p>No references adopted.</p>'}</details>`;$('#snapshot-source').onchange=e=>{updateFilters.source=e.target.value;renderCurriculumReview()};$('#snapshot-date').onchange=e=>{updateFilters.date=e.target.value;renderCurriculumReview()};$('#curriculum-refresh').onclick=()=>saveCurriculum('/api/curriculum/refresh',{source_url:$('#curriculum-source').value});$('#curriculum-import-save').onclick=()=>{try{saveCurriculum('/api/curriculum/import',JSON.parse($('#curriculum-import').value))}catch(e){$('#curriculum-error').textContent='Invalid JSON: '+e.message}};document.querySelectorAll('[data-adopt-snapshot]').forEach(b=>b.onclick=()=>saveCurriculum('/api/curriculum/adopt',{snapshot_id:b.dataset.adoptSnapshot,item_id:b.dataset.adoptItem}));bindLearningItems()}
function curriculum(){const c=state.curriculum||{items:[],resources:[],source_inventory:[]},adoptions=arr(state.learning?.adoptions),base=arr(c.items);return {...c,items:[...base.map(i=>{const a=adoptions.find(a=>a.id===i.id);if(!a)return i;const metadata={};for(const key of ['title','url','access','summary'])if(a[key]!==undefined)metadata[key]=a[key];return {...i,...metadata}}),...adoptions.filter(a=>!base.some(i=>i.id===a.id)).map(a=>({...a,placement:'reference',source_urls:[a.url],assigned_days:[],resource_ids:[],prerequisite_ids:[]}))]}}
function learning(){return state.learning||{states:{},attempts:[],retries:[],snapshots:[],adoptions:[]}}
function learningStatus(id){return learning().states?.[id]?.status||'not_started'}
function itemButton(id,label='Progress & evidence'){return `<button class="link learning-item" data-learning-item="${esc(id)}">${esc(label)} · ${esc(learningStatus(id).replaceAll('_',' '))}</button>`}
function bindLearningItems(){document.querySelectorAll('[data-learning-item]').forEach(b=>b.onclick=()=>openLearningItem(b.dataset.learningItem))}
function appendLinkedLearning(){if(!['prep','study','materials','projects'].includes(tab))return;const items=arr(curriculum().items).filter(i=>tab==='prep'?arr(i.assigned_days).includes(day):tab==='study'?i.id.startsWith('dsa:')||i.id.startsWith('systems:'):tab==='projects'?i.id.startsWith('project:')||i.id.startsWith('milestone:'):i.id.startsWith('exercise:')||i.kind==='checkpoint');if(!items.length)return;const groups=new Map();for(const i of items){const week=arr(i.assigned_days).length?Math.ceil(i.assigned_days[0]/7):'Reference';if(!groups.has(week))groups.set(week,[]);groups.get(week).push(i)}$('#app').insertAdjacentHTML('beforeend',`<section class="section linked-learning"><h2>${tab==='prep'?'Today’s linked learning evidence':'Linked learning evidence by week'}</h2><p class="muted small">These records are shared with Learning map.</p>${[...groups].map(([week,list])=>`<details class="card section" ${tab==='prep'?'open':''}><summary>${week==='Reference'?week:'Week '+week} · ${list.length} items</summary><div class="resource-list section">${list.map(i=>itemButton(i.id,i.title)).join('')}</div></details>`).join('')}</section>`);bindLearningItems();if(tab==='learning')$('#learning-prev').onclick=()=>{learningPage=Math.max(0,learningPage-1);renderLearning()};if(tab==='learning')$('#learning-next').onclick=()=>{learningPage++;renderLearning()}}
function renderLearning(){const c=curriculum(),f=learningFilters,q=f.query.toLowerCase(),items=arr(c.items).filter(i=>(!q||[i.id,i.title,i.summary].join(' ').toLowerCase().includes(q))&&(f.kind==='All'||i.kind===f.kind)&&(f.placement==='All'||i.placement===f.placement)&&(f.status==='All'||learningStatus(i.id)===f.status)&&(f.week==='All'||arr(i.assigned_days).some(d=>String(Math.ceil(d/7))===f.week)));$('#app').innerHTML=`<section class="narrow section"><h2>Learning map</h2><p>Progress and evidence follow the same item throughout the plan. Daily checkboxes record sessions; they do not establish mastery.</p></section><div class="toolbar"><label class="grow">Find an item<input id="learning-query" value="${esc(f.query)}"></label>${[['kind','Kind',[...new Set(arr(c.items).map(i=>i.kind))]],['placement','Placement',['core','reference','prerequisite','duplicate','unavailable']],['week','Week',[...new Set(arr(c.items).flatMap(i=>arr(i.assigned_days).map(d=>String(Math.ceil(d/7)))))].sort((a,b)=>a-b)],['status','Progress',['not_started','studied','practised','demonstrated']]].map(([key,label,values])=>`<label>${label}<select id="learning-${key}">${options(['All',...values],f[key])}</select></label>`).join('')}</div><p class="muted small">${items.length} items · page ${learningPage+1} of ${Math.max(1,Math.ceil(items.length/50))}</p><div class="row"><button id="learning-prev" ${learningPage===0?'disabled':''}>Previous 50</button><button id="learning-next" ${(learningPage+1)*50>=items.length?'disabled':''}>Next 50</button></div><div class="grid">${items.slice(learningPage*50,learningPage*50+50).map(i=>`<article class="card"><span class="eyebrow">${esc(i.kind)} · ${esc(i.placement)}</span><h3>${esc(i.title)}</h3><p>${esc(i.summary)}</p>${itemButton(i.id)}<p class="muted small">${esc(i.id)} · ${arr(i.assigned_days).length?'Days '+esc(arr(i.assigned_days).join(', ')):'Reference; no daily assignment'}</p></article>`).join('')||'<p class="empty">No items match these filters.</p>'}</div><section class="section"><h2>Retry queue</h2><p class="small muted">Retry dates are preparation days.</p>${arr(learning().retries).map(r=>`<div class="card section">Day ${esc(r.due_day)} ${r.backlog?'· backlog':''} ${itemButton(r.item_id,c.items.find(i=>i.id===r.item_id)?.title||r.item_id)}</div>`).join('')||'<p class="muted">No retries queued.</p>'}</section>`;$('#learning-query').oninput=e=>{f.query=e.target.value;learningPage=0;const pos=e.target.selectionStart;renderLearning();$('#learning-query').focus();$('#learning-query').setSelectionRange(pos,pos)};for(const key of ['kind','placement','week','status'])$('#learning-'+key).onchange=e=>{f[key]=e.target.value;learningPage=0;renderLearning()};bindLearningItems();if(tab==='learning')$('#learning-prev').onclick=()=>{learningPage=Math.max(0,learningPage-1);renderLearning()};if(tab==='learning')$('#learning-next').onclick=()=>{learningPage++;renderLearning()}}
function openLearningDetails(id){const c=curriculum(),i=arr(c.items).find(x=>x.id===id);if(!i){toast('This item is not in the curriculum catalog');return}const s=learning().states?.[id]||{},attempts=arr(learning().attempts).filter(a=>(a.item_id||a.id)===id),practice=id.startsWith('dsa:')||id.startsWith('systems:');$('#detail-body').innerHTML=`<span class="eyebrow">${esc(i.kind)} · ${esc(i.placement)}</span><h2>${esc(i.title)}</h2><p>${esc(i.summary)}</p><p class="small muted">${esc(id)}</p><h3>Sources & resources</h3><div class="resource-list">${arr(i.source_urls).map(u=>link(u,'Source')).join('')}${[...new Set([...arr(i.resource_ids),...arr(i.related_resource_ids)])].map(rid=>{const r=arr(c.resources).find(r=>r.id===rid);return r?link(r.url,(rid===i.primary_resource_id?'Primary: ':arr(i.deep_resource_ids).includes(rid)||arr(i.related_resource_ids).includes(rid)?'Optional deeper reference: ':'Resource: ')+r.title):''}).join('')}</div><h3>Prerequisites</h3>${arr(i.prerequisite_ids).map(pid=>itemButton(pid,c.items.find(x=>x.id===pid)?.title||pid)).join('')||'<p class="muted">None specified.</p>'}<label>Progress<select id="learning-progress">${options(['not_started','studied','practised','demonstrated'],s.status||'not_started')}</select></label><label>Notes<textarea id="learning-notes">${esc(s.notes)}</textarea></label><label>Evidence: result, artifact path or URL<textarea id="learning-evidence">${esc(s.evidence)}</textarea></label><button id="save-learning" class="primary">Save progress & evidence</button><p id="learning-error" class="danger" role="alert"></p>${practice?`<h3>Record a practice attempt</h3><div class="toolbar"><label>Prep day<input id="attempt-day" type="number" min="1" max="140" value="${day}"></label><label>Outcome<select id="attempt-outcome">${options(['unsolved','assisted','independent'],'unsolved')}</select></label><label>Minutes<input id="attempt-minutes" type="number" min="0" max="1440" value="25"></label><label>Hints<input id="attempt-hints" type="number" min="0" max="100" value="0"></label><label>Score (optional)<input id="attempt-score" type="number" min="0" max="20"></label></div><label>Attempt notes<textarea id="attempt-notes"></textarea></label><label>Attempt evidence<textarea id="attempt-evidence"></textarea></label><button id="save-attempt">Save attempt</button><h3>Attempts</h3>${attempts.map(a=>`<p>Day ${esc(a.day)} · ${esc(a.outcome)} · ${esc(a.minutes)} min · ${esc(a.hints)} hints<br>${esc(a.notes)} ${esc(a.evidence)}</p>`).join('')||'<p class="muted">No attempts recorded.</p>'}`:''}`;bindLearningItems();$('#save-learning').onclick=()=>saveLearning('/api/learning/state',{id,status:$('#learning-progress').value,notes:$('#learning-notes').value,evidence:$('#learning-evidence').value,version:s.version||0},id);if(practice)$('#save-attempt').onclick=()=>{const payload={id,client_nonce:attemptNonce,day:Number($('#attempt-day').value),outcome:$('#attempt-outcome').value,minutes:Number($('#attempt-minutes').value),hints:Number($('#attempt-hints').value),notes:$('#attempt-notes').value,evidence:$('#attempt-evidence').value};if($('#attempt-score').value!=='')payload.score=Number($('#attempt-score').value);saveLearning('/api/learning/attempt',payload,id)};$('#detail').showModal()}
async function saveLearning(route,payload,id){if(learningSaving)return;learningSaving=true;document.querySelectorAll('#detail-body button').forEach(b=>b.disabled=true);try{await api(route,payload);const incoming=await api('/api/state');state.learning=incoming.learning;state.curriculum=incoming.curriculum;render();openLearningItem(id);toast('Learning evidence saved')}catch(e){$('#learning-error').textContent=e.message;toast(e.message)}finally{learningSaving=false;document.querySelectorAll('#detail-body button').forEach(b=>b.disabled=false)}}
async function saveCurriculum(route,payload){if(learningSaving)return;learningSaving=true;document.querySelectorAll('#app button').forEach(b=>b.disabled=true);try{await api(route,payload);const incoming=await api('/api/state');state.learning=incoming.learning;state.curriculum=incoming.curriculum;render();toast('Curriculum update saved')}catch(e){$('#curriculum-error').textContent=e.message;toast(e.message)}finally{learningSaving=false;document.querySelectorAll('#app button').forEach(b=>b.disabled=false)}}


